#include "stdafx.h"#include "TPSC.h"#include <macros/StrHelps.h>KTPSC::KTPSC(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Tag Name",  "Descriptor",  "Engineering units",  "Decimal Places",  "Direction",  "SP Tracking",  "Automatic mode is permitted",  "Local SP is permitted",  "Remote SP is permitted",  "Manual mode is permitted",  "Initial Mode",  "Power up mode",  "Setpoint initial mode",  "Setpoint power up mode",  "Power Up Output",  "Failsafe Out",  "Use initial LSP value",  "PV high range",  "PV low range",  "SP high limit",  "SP low limit",  "AT Output high limit",  "AT Output low limit",  "SP rate limit down",  "SP rate limit up",  "RSP units type",  "Ratio / Bias type",  "Local Bias",  "Ratio",  "Gain",  "Reset (minutes)",  "Rate (minutes)",  "Gain 2",  "Reset 2 (minutes)",  "Rate 2 (minutes)",  "Accutune",  "Fuzzy",  "Alarm 1 Setpoint 1",  "Alarm 1 Setpoint 2",  "Alarm 2 Setpoint 1",  "Alarm 2 Setpoint 2",  "Alarm Hysteresis (%)",  "Dead Band (%)",  "Motor Travel Time (sec)",};BOOL KTPSC::OnParsingSingleText( std::string &szText, RECTL *rc ){  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  if( m_CurParameterID!=-1 )  {    char szJ[2][64] = {};    if( !strcmp( s_MyParameters[m_CurParameterID], "Alarm 1 Setpoint 1") )    {      SplitString( szText.c_str(), szJ, ',', false );      CStringA cs( szJ[1] );cs.Trim( " " );      AddParam( "Alarm1_1", szJ[0] );      AddParam( "Setpoint1_1", cs );      m_CurParameterID = -1;      return TRUE;    }    else if( !strcmp( s_MyParameters[m_CurParameterID], "Alarm 1 Setpoint 2") )    {      SplitString( szText.c_str(), szJ, ',', false );      CStringA cs( szJ[1] );cs.Trim( " " );      AddParam( "Alarm1_2", szJ[0] );      AddParam( "Setpoint1_2", cs );      m_CurParameterID = -1;      return TRUE;    }    else if( !strcmp( s_MyParameters[m_CurParameterID], "Alarm 2 Setpoint 1") )    {      SplitString( szText.c_str(), szJ, ',', false );      CStringA cs( szJ[1] );cs.Trim( " " );      AddParam( "Alarm2_1", szJ[0] );      AddParam( "Setpoint2_1", cs );      m_CurParameterID = -1;      return TRUE;    }    else if( !strcmp( s_MyParameters[m_CurParameterID], "Alarm 2 Setpoint 2") )    {      SplitString( szText.c_str(), szJ, ',', false );      CStringA cs( szJ[1] );cs.Trim( " " );      AddParam( "Alarm2_2", szJ[0] );      AddParam( "Setpoint2_2", cs );      m_CurParameterID = -1;      return TRUE;    }    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    /*CStringA s;    if( 7==m_CurParameterID )      s.Format( "DisableValue = %s", szText.c_str() );*/    //if( !s.IsEmpty() )    m_settings.push_back( szText.c_str() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;  }  if( !strncmp(szText.c_str(),"PCVS", 4) )    return TRUE;  return FALSE;}